-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'TESTES DE FRONTEND' and a.numero = 4
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 4 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 04', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 04 (10 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/TESTES-DE-FRONTEND/ATIVIDADES/ATIVIDADE-PRATICA-AULA-04.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique o que o teste de integração verifica no front-end.', 0.2, 'O teste de integração verifica **várias partes trabalhando juntas**: o HTML gerado, os eventos, a regra de validação e a mensagem que aparece na tela.', 'Palavras-chave: várias partes juntas; HTML, eventos, validação, mensagem. Nota cheia (0,2): ideia de partes integradas com exemplo. Metade (0,1): "testa a tela" sem a ideia de partes juntas. Zero (0): confunde com teste de uma função isolada.'),
      (v_atividade, 1, 2, 'Diga onde ele fica na pirâmide de testes, comparando a velocidade dele com a do teste unitário e a do teste E2E.', 0.4, 'Fica no **meio da pirâmide**: é **mais lento que o unitário** (monta a tela e dispara eventos) e **bem mais rápido que o E2E** (não abre o navegador nem sobe o sistema inteiro). Por isso há menos testes de integração que unitários e mais que E2E.', 'Palavras-chave: meio da pirâmide; mais lento que unitário; mais rápido que E2E. Nota cheia (0,4): posição + as duas comparações. Metade (0,2): posição com só uma comparação, ou comparações sem a posição. Zero (0): diz que fica no topo ou na base.'),
      (v_atividade, 1, 3, 'Explique o que é o JSDOM e por que ele deixa o teste de integração rápido, respondendo à dúvida da equipe sobre o navegador.', 0.4, 'O **JSDOM é um DOM simulado** em JavaScript, que roda dentro do Node. O teste monta a tela, procura elementos e dispara eventos **sem abrir o navegador**, por isso é rápido. Resposta à equipe: o teste de integração **não abre o navegador**; quem abre é o E2E.', 'Palavras-chave: DOM simulado; roda no Node; sem abrir navegador; rápido. Nota cheia (0,4): definição + motivo da rapidez + resposta à dúvida. Metade (0,2): definição sem a ligação com a rapidez ou sem responder à dúvida. Zero (0): diz que o JSDOM é um navegador real.'),
      (v_atividade, 2, 1, 'Escreva o comando npm que instala, como dependências de desenvolvimento, o jsdom, a Testing Library do DOM, o user-event e o jest-dom.', 0.2, 'npm install -D jsdom @testing-library/dom @testing-library/user-event @testing-library/jest-dom', 'Palavras-chave: npm install -D (ou --save-dev); os quatro pacotes. Nota cheia (0,2): comando com -D e os quatro pacotes. Metade (0,1): falta um pacote ou falta o -D. Zero (0): comando sem relação ou sem os pacotes da Testing Library.'),
      (v_atividade, 2, 2, 'Escreva o arquivo vitest.config.js com o ambiente jsdom e o arquivo de setup tests/setup.js, e escreva o conteúdo do tests/setup.js.', 0.4, 'vitest.config.js: import { defineConfig } from ''vitest/config''; export default defineConfig({ test: { environment: ''jsdom'', setupFiles: [''./tests/setup.js''] } }); — tests/setup.js: import ''@testing-library/jest-dom/vitest'';', 'Palavras-chave: defineConfig; environment ''jsdom''; setupFiles; import do jest-dom/vitest. Nota cheia (0,4): os dois arquivos corretos. Metade (0,2): só um dos arquivos certo, ou falta o environment ou o setupFiles. Zero (0): configuração sem jsdom e sem setup.'),
      (v_atividade, 2, 3, 'Explique o que muda na instalação e na montagem do componente se o projeto usar React, e o que continua igual.', 0.4, 'Em React, troca-se **@testing-library/dom por @testing-library/react** e monta-se o componente com **render(<Componente />)** em vez de colocar o elemento no document.body. **Continuam iguais** as queries (getByRole, getByLabelText...), o **userEvent** e os matchers do jest-dom.', 'Palavras-chave: @testing-library/react; render; queries e userEvent iguais. Nota cheia (0,4): o que muda (pacote e render) + o que continua igual. Metade (0,2): só o que muda ou só o que continua igual. Zero (0): diz que tudo muda ou que não dá para testar React.'),
      (v_atividade, 3, 1, 'Diga se o teste do colega testa o comportamento ou a implementação e por quê.', 0.2, 'Testa a **implementação**: procura o botão pela **classe CSS** e confere uma **variável interna**, coisas que o usuário não vê. Por isso quebrou sem mudança visível.', 'Palavras-chave: implementação; classe CSS; variável interna; o usuário não vê. Nota cheia (0,2): implementação + motivo. Metade (0,1): implementação sem motivo. Zero (0): diz que testa o comportamento.'),
      (v_atividade, 3, 2, 'Reescreva o teste para clicar no botão como o usuário faria e conferir o que aparece na tela (query por papel, userEvent com await e expect do texto "Seguindo").', 0.4, 'const usuario = userEvent.setup(); document.body.append(criarBotaoSeguir({ aoAlternar: vi.fn() })); await usuario.click(screen.getByRole(''button'', { name: ''Seguir'' })); expect(screen.getByRole(''button'', { name: ''Seguindo'' })).toBeInTheDocument(); (ou expect(botao).toHaveTextContent(''Seguindo'')).', 'Palavras-chave: getByRole(''button'', { name: ''Seguir'' }); userEvent; await; expect do texto Seguindo. Nota cheia (0,4): query por papel + clique com await + expect do texto. Metade (0,2): falta o await ou o expect confere outra coisa, ou usa getByText no lugar do papel. Zero (0): continua usando classe CSS ou variável interna.'),
      (v_atividade, 3, 3, 'Explique a relação entre testar pelo comportamento e o teste de caixa preta (3.1), e por que o novo teste não quebra quando a classe CSS muda.', 0.4, 'Testar pelo comportamento é **caixa preta**: o teste olha **entradas e saídas visíveis** (clique e texto na tela), **sem conhecer o código** interno. Como o novo teste procura o botão pelo **papel e pelo nome**, trocar a classe CSS não muda o que ele encontra; ele só quebra se o **comportamento** mudar.', 'Palavras-chave: caixa preta; entradas e saídas; sem olhar o código; papel e nome não dependem de CSS. Nota cheia (0,4): relação com caixa preta + motivo de não quebrar. Metade (0,2): só uma das duas partes. Zero (0): confunde com caixa branca.'),
      (v_atividade, 4, 1, 'Escreva a ordem de prioridade das queries da Testing Library, da primeira à última.', 0.2, 'getByRole → getByLabelText → getByPlaceholderText → getByText → getByTestId (último recurso).', 'Palavras-chave: as cinco queries na ordem. Nota cheia (0,2): ordem completa e correta. Metade (0,1): getByRole primeiro e getByTestId por último, com erro no meio. Zero (0): getByTestId como primeira opção.'),
      (v_atividade, 4, 2, 'Escreva a query que você usaria para cada um dos três elementos (campo Senha, botão Cadastrar e título) e justifique a escolha de cada uma.', 0.4, 'Campo Senha: **screen.getByLabelText(''Senha'')** (o campo tem rótulo; também vale getByRole com o nome, mas campo de senha não tem papel textbox). Botão: **screen.getByRole(''button'', { name: ''Cadastrar'' })** (papel + nome, prioridade 1). Título: **screen.getByRole(''heading'', { name: ''Crie sua conta'' })** (é um título, papel heading). Cada escolha encontra o elemento como o usuário o percebe.', 'Palavras-chave: getByLabelText(''Senha''); getByRole(''button'', ...Cadastrar); getByRole(''heading'', ...). Nota cheia (0,4): as três queries certas com justificativa. Metade (0,2): duas certas ou as três sem justificativa; getByText no título vale metade. Zero (0): querySelector, classe CSS ou testid sem motivo.'),
      (v_atividade, 4, 3, 'Explique quando o getByTestId é aceitável e por que buscar pelo papel também revela problemas de acessibilidade.', 0.4, 'O **getByTestId** é aceitável só como **último recurso**, quando o elemento não tem papel, rótulo nem texto visível para encontrar (e com justificativa). Buscar pelo **papel** é buscar como o **leitor de tela** encontra: se o teste não acha o botão pelo papel e nome, o leitor de tela também não acha, então o teste **revela problema de acessibilidade** (rótulo ou papel faltando no HTML).', 'Palavras-chave: último recurso; sem papel/rótulo/texto; leitor de tela; acessibilidade. Nota cheia (0,4): quando usar testid + ligação com acessibilidade. Metade (0,2): só uma das partes. Zero (0): recomenda testid como padrão.'),
      (v_atividade, 5, 1, 'Explique a diferença entre getBy, queryBy e findBy.', 0.2, '**getBy** encontra o elemento que **deve existir** (se não existir, o teste falha com erro). **queryBy** devolve **null** se não encontrar (serve para conferir que algo **não está** na tela). **findBy** **espera** o elemento aparecer (assíncrono, usado com await).', 'Palavras-chave: getBy deve existir/erro; queryBy null/ausência; findBy espera/assíncrono. Nota cheia (0,2): as três diferenças. Metade (0,1): duas das três. Zero (0): diz que são iguais.'),
      (v_atividade, 5, 2, 'Explique por que o teste do colega dá erro e reescreva-o com a query certa.', 0.4, 'O **getByText lança erro** quando o elemento não existe, então o teste quebra **antes do expect**. O certo é usar **queryByText**, que devolve null: expect(screen.queryByText(''A senha deve ter no mínimo 6 dígitos'')).not.toBeInTheDocument();', 'Palavras-chave: getBy lança erro; queryByText; not.toBeInTheDocument. Nota cheia (0,4): causa + teste reescrito com queryBy. Metade (0,2): só a causa ou só o código. Zero (0): mantém getBy ou usa findBy sem await.'),
      (v_atividade, 5, 3, 'Dê um exemplo de situação em que o findBy é a escolha certa e escreva a linha de código com o await.', 0.4, 'Quando algo **aparece depois de um tempo**, por exemplo a mensagem "Cadastro realizado!" que surge depois de a tela esperar a resposta do servidor (ou uma lista carregada de uma API). Código: const aviso = await screen.findByText(''Cadastro realizado!''); expect(aviso).toBeInTheDocument();', 'Palavras-chave: aparece depois/assíncrono; await; findBy. Nota cheia (0,4): situação assíncrona + linha com await findBy. Metade (0,2): situação certa sem o await, ou código certo sem situação. Zero (0): situação síncrona ou findBy para conferir ausência.'),
      (v_atividade, 6, 1, 'Escreva o Arrange: o vi.fn do callback, a montagem do botão no document.body e a criação do usuário com userEvent.setup().', 0.2, 'const aoAlternar = vi.fn(); document.body.append(criarBotaoSeguir({ aoAlternar })); const usuario = userEvent.setup();', 'Palavras-chave: vi.fn; document.body.append (ou appendChild); criarBotaoSeguir({ aoAlternar }); userEvent.setup(). Nota cheia (0,2): as três linhas. Metade (0,1): falta uma das três. Zero (0): sem montagem do botão.'),
      (v_atividade, 6, 2, 'Escreva o Act e o Assert: clicar no botão Seguir e conferir o texto "Seguindo", o aria-pressed="true" e a chamada de aoAlternar com true.', 0.4, 'await usuario.click(screen.getByRole(''button'', { name: ''Seguir'' })); const botao = screen.getByRole(''button'', { name: ''Seguindo'' }); expect(botao).toHaveAttribute(''aria-pressed'', ''true''); expect(aoAlternar).toHaveBeenCalledWith(true);', 'Palavras-chave: await usuario.click; getByRole Seguir/Seguindo; toHaveAttribute(''aria-pressed'', ''true''); toHaveBeenCalledWith(true). Nota cheia (0,4): clique com await + as três conferências (texto, atributo, callback). Metade (0,2): falta o await ou uma das conferências. Zero (0): não clica ou não confere nada da tela.'),
      (v_atividade, 6, 3, 'Escreva um segundo teste que clica duas vezes e confere que o botão volta para "Seguir" e que aoAlternar foi chamado por último com false.', 0.4, 'it(''volta para Seguir no segundo clique'', async () => { const aoAlternar = vi.fn(); document.body.append(criarBotaoSeguir({ aoAlternar })); const usuario = userEvent.setup(); const botao = screen.getByRole(''button'', { name: ''Seguir'' }); await usuario.click(botao); await usuario.click(botao); expect(screen.getByRole(''button'', { name: ''Seguir'' })).toHaveAttribute(''aria-pressed'', ''false''); expect(aoAlternar).toHaveBeenLastCalledWith(false); });', 'Palavras-chave: dois cliques com await; texto Seguir; aria-pressed false; toHaveBeenLastCalledWith(false) (ou toHaveBeenNthCalledWith(2, false)). Nota cheia (0,4): teste completo. Metade (0,2): dois cliques e texto certo, mas sem conferir a última chamada (ou sem async/await). Zero (0): um clique só.'),
      (v_atividade, 7, 1, 'Explique o que o userEvent.setup() cria e por que as ações dele precisam de await.', 0.2, 'O userEvent.setup() cria um **"usuário" simulado** que dispara a **sequência real de eventos** (foco, teclado, mouse, clique). Todas as ações dele são **assíncronas** (devolvem Promise); sem **await**, o expect pode rodar **antes** de o clique terminar.', 'Palavras-chave: usuário simulado; sequência real de eventos; assíncrono/Promise; expect antes do clique. Nota cheia (0,2): o que cria + por que await. Metade (0,1): só uma das partes. Zero (0): diz que o await é opcional.'),
      (v_atividade, 7, 2, 'Explique a causa do problema (2) e escreva o beforeEach que o resolve.', 0.4, 'O primeiro teste deixou o botão no **document.body**, e o segundo montou outro: ficaram **dois botões** na tela. Solução: limpar o corpo antes de cada teste: beforeEach(() => { document.body.innerHTML = ''''; });', 'Palavras-chave: sobra do teste anterior; dois botões; beforeEach; document.body.innerHTML = ''''. Nota cheia (0,4): causa + beforeEach correto. Metade (0,2): só a causa ou só o código. Zero (0): sugere apagar o segundo teste.'),
      (v_atividade, 7, 3, 'Explique por que um teste não pode depender de outro e o que acontece com a confiança na suíte quando os testes passam ou falham ao acaso.', 0.4, 'Cada teste precisa ser **independente**: rodar sozinho, em qualquer ordem, com o mesmo resultado. Se um depende do outro, mudar a ordem ou rodar só um quebra o teste. Testes que passam e falham **ao acaso (instáveis)** fazem a equipe **deixar de confiar** na suíte e ignorar falhas reais.', 'Palavras-chave: independente; qualquer ordem; instável/ao acaso; perde a confiança. Nota cheia (0,4): independência + efeito na confiança. Metade (0,2): só uma das partes. Zero (0): diz que a ordem dos testes deve ser fixa.'),
      (v_atividade, 8, 1, 'Diga o que conferem os matchers toBeInTheDocument, toBeDisabled e toHaveValue.', 0.2, '**toBeInTheDocument** confere se o elemento **está na página**; **toBeDisabled** confere se está **desabilitado**; **toHaveValue** confere se o campo tem o **valor digitado**.', 'Palavras-chave: está na página; desabilitado; valor do campo. Nota cheia (0,2): os três. Metade (0,1): dois. Zero (0): um ou nenhum.'),
      (v_atividade, 8, 2, 'Escreva os expects que conferem que o campo E-mail tem o valor digitado e que o botão Cadastrar está desabilitado.', 0.4, 'expect(screen.getByLabelText(''E-mail'')).toHaveValue(''ana@escola.com''); expect(screen.getByRole(''button'', { name: ''Cadastrar'' })).toBeDisabled();', 'Palavras-chave: getByLabelText(''E-mail''); toHaveValue(''ana@escola.com''); getByRole button Cadastrar; toBeDisabled(). Nota cheia (0,4): os dois expects certos. Metade (0,2): um dos dois certo. Zero (0): matchers trocados ou sem query.'),
      (v_atividade, 8, 3, 'Escreva o expect que confere que a mensagem de aviso da senha está visível e explique a diferença entre toBeInTheDocument e toBeVisible.', 0.4, 'expect(screen.getByText(''A senha deve ter no mínimo 6 dígitos'')).toBeVisible(); — **toBeInTheDocument** só confere que o elemento **existe na página**; **toBeVisible** confere que, além de existir, **o usuário consegue vê-lo** (não está escondido por display none, hidden ou opacidade zero).', 'Palavras-chave: getByText da mensagem; toBeVisible; existe × usuário vê. Nota cheia (0,4): expect certo + diferença. Metade (0,2): só o expect ou só a diferença. Zero (0): diz que são iguais.'),
      (v_atividade, 9, 1, 'Diga a que parte do padrão AAA corresponde a pré-condição, os passos e o resultado esperado do caso de teste.', 0.2, '**Pré-condição = Arrange** (montar o formulário); **passos = Act** (digitar e clicar); **resultado esperado = Assert** (conferir a mensagem).', 'Palavras-chave: pré-condição/Arrange; passos/Act; resultado/Assert. Nota cheia (0,2): as três correspondências. Metade (0,1): duas. Zero (0): correspondências trocadas.'),
      (v_atividade, 9, 2, 'Escreva o teste completo do CT-07 (montagem do formulário, userEvent.type nos campos pelo rótulo, clique no botão pelo papel e expect da mensagem).', 0.4, 'it(''CT-07: cadastra com dados válidos'', async () => { document.body.append(criarFormCadastro()); const usuario = userEvent.setup(); await usuario.type(screen.getByLabelText(''E-mail''), ''ana@escola.com''); await usuario.type(screen.getByLabelText(''Senha''), ''123456''); await usuario.click(screen.getByRole(''button'', { name: ''Cadastrar'' })); expect(screen.getByText(''Cadastro realizado!'')).toBeInTheDocument(); }); (findByText com await também vale.)', 'Palavras-chave: montagem do formulário; userEvent.type com await; getByLabelText; getByRole button; expect da mensagem. Nota cheia (0,4): teste completo e correto. Metade (0,2): falta o await, ou uma das digitações, ou o expect. Zero (0): não segue o caso de teste.'),
      (v_atividade, 9, 3, 'Explique por que esse teste é de funcionalidade (4.1) e de caixa preta (3.1), e qual a vantagem de executar o caso do plano de forma automática.', 0.4, 'É de **funcionalidade (4.1)** porque confere se a tela **faz o que o requisito pede** (cadastrar e avisar). É de **caixa preta (3.1)** porque usa só **entradas e saídas visíveis**, sem olhar o código. Executar de forma **automática** permite **repetir o caso a cada alteração em segundos**, sem esforço manual, servindo de teste de regressão.', 'Palavras-chave: faz o que o requisito pede; entradas e saídas sem código; repetir automático/regressão. Nota cheia (0,4): as três ideias. Metade (0,2): duas. Zero (0): classifica como desempenho ou caixa branca.'),
      (v_atividade, 10, 1, 'Diga qual é o defeito encontrado e o tipo de teste (da classificação da aula 1) a que ele pertence.', 0.2, 'Defeito: **a mensagem de aviso da senha não aparece**, então o usuário não sabe por que não consegue avançar. Tipo: **teste de funcionalidade** (4.1) — a tela não cumpre o comportamento esperado (também se aceita citar o impacto na usabilidade).', 'Palavras-chave: mensagem não aparece; funcionalidade. Nota cheia (0,2): defeito + tipo. Metade (0,1): só o defeito ou só usabilidade sem funcionalidade. Zero (0): diz que o defeito é o botão desabilitado.'),
      (v_atividade, 10, 2, 'Escreva o teste que digita a senha de 5 caracteres e confere o botão desabilitado e a mensagem de aviso, e diga qual linha falha hoje.', 0.4, 'it(''avisa quando a senha é curta'', async () => { document.body.append(criarFormCadastro()); const usuario = userEvent.setup(); await usuario.type(screen.getByLabelText(''Senha''), ''12345''); expect(screen.getByRole(''button'', { name: ''Cadastrar'' })).toBeDisabled(); expect(screen.getByText(''A senha deve ter no mínimo 6 dígitos'')).toBeInTheDocument(); }); — Hoje **falha a linha do getByText da mensagem** (o botão desabilitado passa).', 'Palavras-chave: senha de 5 caracteres com await; toBeDisabled; getByText da mensagem; linha que falha. Nota cheia (0,4): teste completo + linha que falha. Metade (0,2): teste certo sem indicar a linha, ou falta uma das conferências. Zero (0): usa queryBy esperando ausência da mensagem.'),
      (v_atividade, 10, 3, 'Explique por que anexar o teste que falha ao relatório ajuda a equipe e o que deve acontecer com esse teste depois da correção.', 0.4, 'O teste que falha é a **prova reproduzível** do defeito: a equipe roda e **vê a falha**, sem depender de descrição. Depois da correção, o **mesmo teste deve passar** e **fica na suíte** como **teste de regressão**, para avisar se o defeito voltar.', 'Palavras-chave: prova reproduzível; passa depois da correção; fica na suíte/regressão. Nota cheia (0,4): as duas partes. Metade (0,2): só uma. Zero (0): diz para apagar o teste depois da correção.');
end $$;
